                    sb.Append($"{t->tm_hour:D2}:{t->tm_min:D2}:{t->tm_sec:D2}"); break;
                case (byte)'R': sb.Append($"{t->tm_hour:D2}:{t->tm_min:D2}"); break;
                case (byte)'D':
