        => CompilerRtValue<T>(__udivti3(CompilerRtBits(lhs), CompilerRtBits(rhs)));

    public static T __umodti3<T>(T lhs, T rhs) where T : unmanaged
        => CompilerRtValue<T>(__umodti3(CompilerRtBits(lhs), CompilerRtBits(rhs)));

