        bool sign = (b >> 63) != 0;
        int exp = (int)((b >> 52) & 0x7FF);   // biased binary64 exponent
        ulong frac = b & 0x000F_FFFF_FFFF_FFFFUL; // 52-bit fraction

        if (exp == 0x7FF)
