    private static void ObserveGuestTimer(GuestSignalState state, long now)
    {
        if (state.Due == 0 || now < state.Due) return;
        if (state.Actions[13].Handler != 1) state.Pending |= 1UL << 13;
        if (state.Interval == 0) state.Due = 0;
