                    savedMask = state.Mask;
                    state.Mask |= action.Mask;
                    state.Mask |= 1UL << (sig - 1);
                    if ((unchecked((uint)action.Flags) & 0x80000000U) != 0) state.Actions[sig - 1] = default;
