            ulong bytes = checked((ulong)count * (ulong)sizeof(byte*));
            for (int i = 0; i < count; i++) bytes = checked(bytes + (ulong)strlen(native[i]) + 1);
            byte** result = (byte**)malloc(bytes);
            if (result == null) { errno = ENOMEM; return null; }
