    {
        if (attribute == null || size == null) return EINVAL;
        var registry = PthreadAttributesFor(RuntimeState);
        lock (registry)
        {
            if (!registry.Attributes.TryGetValue(*attribute, out var value)) return EINVAL;
            *size = (ulong)value.StackSize;
