    {
        if (state is not (PTHREAD_CANCEL_ENABLE or PTHREAD_CANCEL_DISABLE)) return EINVAL;
        if (previous != null) *previous = RuntimeThread.CancellationState;
        RuntimeThread.CancellationState = state;
        return 0;
    }

