// VaArg / VaList are NESTED in Libc (like LongJmpToken) so the predefined-type
// alias the emitter writes — `using unsafe va_list = Libc.VaList;` — resolves,
// while `using static Libc;` still brings them into scope by bare name for the
// `params ReadOnlySpan<VaArg>` / `new VaList(...)` the emitter generates.
public static unsafe partial class Libc
{

/// <summary>
/// One actual argument passed through a C variadic call (<c>...</c>). dotcc
/// lowers a variadic C function <c>T f(fixed…, ...)</c> to a C# method with a
/// trailing <c>params ReadOnlySpan<VaArg></c>; C# applies the implicit conversions below to
/// each variadic actual at the call site, so the marshalling rides ordinary
/// overload resolution — no boxing, and (unlike <c>object[]</c>) it can carry
/// raw pointers.
/// </summary>
/// <remarks>
/// The emitter applies C's default argument promotions before these operators:
/// small integer types widen to <c>int</c> and <c>float</c> to <c>double</c>.
/// Explicit promotion avoids ambiguous C# overload resolution for unsigned
/// short, which otherwise converts equally well through int and uint.
/// A typed <c>T*</c> reaches the
/// <c>void*</c> operator through the standard <c>T* → void*</c> conversion (one
/// standard + one user-defined step, which C# permits). Storage is a single
/// 8-byte integer/pointer slot plus a double slot; <c>va_arg(ap, T)</c> reads
/// back through the matching accessor the emitter picks for <c>T</c>.
/// </remarks>
public readonly struct VaArg
{
    private readonly long _bits;   // integers and pointer addresses
    private readonly double _dbl;  // floating-point values

    private VaArg(long bits, double dbl) { _bits = bits; _dbl = dbl; }

    // FROM each C argument type (applied at the call site by C# on each
    // variadic actual). The emitter explicitly promotes char/short → int and
    // float → double before reaching these; direct runtime callers remain valid.
    public static implicit operator VaArg(byte v) => new(v, 0);
    public static implicit operator VaArg(int v) => new(v, 0);
    public static implicit operator VaArg(uint v) => new(v, 0);
    public static implicit operator VaArg(long v) => new(v, 0);
    public static implicit operator VaArg(ulong v) => new(unchecked((long)v), 0);
    public static implicit operator VaArg(double v) => new(0, v);
    public static implicit operator VaArg(CBool v) => new((int)v, 0);
    public static unsafe implicit operator VaArg(void* p) => new((long)p, 0);

    // TO the type requested by `va_arg(ap, T)`, which the emitter lowers to
    // `(T)ap.Next()`. A typedef alias resolves through C# (e.g. `(size_t)` is
    // `(ulong)`), so no per-typedef knowledge is needed here. Pointer reads go
    // via `NextPtr()` → `(T*)(void*)`, a standard explicit pointer conversion.
    public static explicit operator int(VaArg a) => unchecked((int)a._bits);
    public static explicit operator uint(VaArg a) => unchecked((uint)a._bits);
    public static explicit operator long(VaArg a) => a._bits;
    public static explicit operator ulong(VaArg a) => unchecked((ulong)a._bits);
    public static explicit operator double(VaArg a) => a._dbl;
    public static explicit operator float(VaArg a) => (float)a._dbl;
    public static unsafe explicit operator void*(VaArg a) => (void*)a._bits;
}

/// <summary>
/// C <c>va_list</c> — a cursor over the borrowed <see cref="VaArg"/> span a variadic
/// function received. A stack-bound value type, so passing a <c>va_list</c> to another
/// function (the <c>lua_pushfstring</c> → <c>luaO_pushvfstring</c> idiom) and
/// <c>va_copy</c> both work by struct copy: each holder advances its own
/// independent index over the shared read-only argument span.
/// </summary>
/// <remarks>
/// <c>va_start(ap, last)</c> lowers to <c>ap = new VaList(_va)</c> (the
/// synthesized params span; <c>last</c> is ignored, as the span already holds
/// exactly the variadic actuals). <c>va_arg(ap, T)</c> lowers to the matching
/// <c>Next…()</c> accessor — pointers via <c>(T)ap.NextPtr()</c>.
/// <c>va_end(ap)</c> → <see cref="End"/> (a no-op). <c>va_copy(d, s)</c> →
/// <c>d = s</c>.
/// </remarks>
public ref struct VaList
{
    private readonly ReadOnlySpan<VaArg> _args;
    private int _i;

    public VaList(ReadOnlySpan<VaArg> args) { _args = args; _i = 0; }

    // `va_arg(ap, T)` for a scalar T lowers to `(T)ap.Next()`; for a pointer T
    // to `(T)ap.NextPtr()`. Both advance the cursor by one.
    public VaArg Next() => _args[_i++];
    public unsafe void* NextPtr() => (void*)_args[_i++];

    public void End() { }
}

}


#nullable restore
// ---- VectorIoLib.cs ----
#nullable enable


public static unsafe partial class Libc
{
    // Linux LP64 iovec. The void* public boundary also accepts generated iovec*.
    // Fields are populated through caller-owned memory, not managed assignments.
    [StructLayout(LayoutKind.Sequential)]
    private struct VectorIoEntry { public void* Base; public ulong Length; }

    public static long readv(int fd, void* vectors, int count) => TransferVector(fd, vectors, count, false);
    public static long writev(int fd, void* vectors, int count) => TransferVector(fd, vectors, count, true);

    private static long TransferVector(int fd, void* vectors, int count, bool writing)
    {
        if (count < 0 || count > 1024) { errno = EINVAL; return -1; }
        if (vectors == null && count != 0) { errno = EFAULT; return -1; }
        if (SlotByFd(fd) is not { } slot) { errno = EBADF; return -1; }
        var entries = (VectorIoEntry*)vectors;
        ulong total = 0;
        for (int i = 0; i < count; i++)
        {
            if (entries[i].Length > (ulong)long.MaxValue - total) { errno = EINVAL; return -1; }
            if (entries[i].Base == null && entries[i].Length != 0) { errno = EFAULT; return -1; }
            total += entries[i].Length;
        }
        if (total == 0) return 0;
        // Like Linux's MAX_RW_COUNT, one operation can transfer fewer than the
        // requested bytes. Bound a single BCL buffer without summation overflow.
        int capacity = (int)Math.Min(total, 0x7ffff000UL);
        byte[] buffer;
        try { buffer = global::System.Buffers.ArrayPool<byte>.Shared.Rent(capacity); }
        catch (OutOfMemoryException) { errno = ENOMEM; return -1; }
        try
        {
            if (writing)
            {
                int offset = 0;
                for (int i = 0; i < count && offset < capacity; i++)
                {
                    int size = (int)Math.Min(entries[i].Length, (ulong)(capacity - offset));
                    new ReadOnlySpan<byte>(entries[i].Base, size).CopyTo(buffer.AsSpan(offset, size));
                    offset += size;
                }
            }
            long transferred;
            // One socket send/receive preserves a datagram or TCP short-I/O
            // boundary. Never issue one blocking receive per vector.
            lock (slot)
            {
                fixed (byte* bytes = buffer)
                    transferred = writing ? write(fd, bytes, (ulong)capacity) : read(fd, bytes, (ulong)capacity);
            }
            if (!writing && transferred > 0)
            {
                int offset = 0;
                for (int i = 0; i < count && offset < transferred; i++)
                {
                    int size = (int)Math.Min(entries[i].Length, (ulong)(transferred - offset));
                    buffer.AsSpan(offset, size).CopyTo(new Span<byte>(entries[i].Base, size));
                    offset += size;
                }
            }
            return transferred;
        }
        finally { global::System.Buffers.ArrayPool<byte>.Shared.Return(buffer, clearArray: true); }
    }
}


#nullable restore
// ---- VfprintfLib.cs ----
#nullable enable


public static unsafe partial class Libc
{
    /// <summary>Write a fixed va_list cursor without repacking it into varargs.
    /// File/socket output preserves formatted bytes, including embedded NULs.</summary>
    public static int vfprintf(FILE* stream, byte* format, scoped VaList arguments)
    {
        var slot = Slot(stream);
        if (slot == null || slot.Kind == FileSlot.K.In || slot.Stream is { CanWrite: false })
        {
            errno = EBADF;
            if (slot != null) slot.Err = true;
            return -1;
        }
        byte* buffer = null;
        try
        {
            // Format once: evaluating %n twice during sizing would repeat its
            // observable write. vasprintf owns the byte-oriented cursor formatter.
            int count = vasprintf(&buffer, format, arguments);
            if (count < 0) return -1;
            if (slot.BufferMode < 0 && (slot.Kind is FileSlot.K.Out or FileSlot.K.Err))
            {
                // Console redirection uses TextWriter, while the return value is
                // still the number of C bytes, not the decoded character count.
                var writer = slot.Kind == FileSlot.K.Err ? Console.Error : Console.Out;
                writer.Write(Encoding.UTF8.GetString(buffer, count));
            }
            else
            {
                for (int i = 0; i < count; i++)
                    if (!WriteByteSlot(slot, buffer[i])) { slot.Err = true; return -1; }
            }
            return count;
        }
        catch (IOException) { slot.Err = true; errno = EIO; return -1; }
        catch (ObjectDisposedException) { slot.Err = true; errno = EBADF; return -1; }
        catch (UnauthorizedAccessException) { slot.Err = true; errno = EACCES; return -1; }
        finally { free(buffer); }
    }

    public static int vprintf(byte* format, scoped VaList arguments)
        => vfprintf(stdout, format, arguments);

    public static int vsprintf(byte* destination, byte* format, scoped VaList arguments)
        => new SprintfBuilder(destination, format, capacity: -1).Arguments(arguments).Done();
}


